Method.Implementation:
	$$$TRACE("Inside Select prfnltype Method")
	set tPRVDR=pRequest.StringValue
    $$$TRACE("Provider ID: "_tPRVDR)
	set pResponse = ##class(IHC.ITF.DStruc.Request.CORPPRV.ListOfMdmExtraFields).%New()
	set list =  ##class(%ListOfObjects).%New()
	// So this get all the records
	set pRes = ##class(EnsLib.SQL.Snapshot).%New()
	set pRes.MaxRowsToGet = -1
	set tSQL = "SELECT CADVFA.FCILITY_ID AS FCILITY_ID, CADVFA.PRMRY_FLG As PRMRY_FLG, CADVFA.PRVDR_ID As PRVDR_ID, FACI.FCILITY_NM As FCILITY_NM, 999 As SPCLTY_ID, '999' As SPCLTY_DSC, 999 As VSP_PRVDR_ID, '999' As PRIMARY_FLG "
    set tSQL = tSQL _ "FROM CORPPRV.ADV_FACILITY_AFFILIATION CADVFA, FACILITY.FCILITY "
    set tSQL = tSQL _ "FACI WHERE CADVFA.FCILITY_ID = FACI.FCILITY_ID AND CADVFA.PRVDR_ID = ? "
    set tSQL = tSQL _ " UNION "
    set tSQL = tSQL _ "SELECT 999, '999', 999, '999', CADVSP.SPCLTY_ID, CSP.SPCLTY_DSC, CADVSP.PRVDR_ID, CADVSP.PRIMARY_FLG "
    set tSQL = tSQL _ "FROM CORPPRV.ADV_PRVDR_SPCLTY CADVSP, CORPPRV.SPECIALTY CSP "
    set tSQL = tSQL _ "WHERE CSP.SPCLTY_ID = CADVSP.SPCLTY_ID AND CADVSP.PRVDR_ID = ?"

	set ioParms=2
	set ioParms(1)=tPRVDR
	set ioParms(1,"SqlType")=3
	set ioParms(2)=tPRVDR
	set ioParms(2,"SqlType")=3

 	set tSC = ..Adapter.ExecuteQueryParmArray(.pRes,tSQL,.ioParms)


	if tSC = 1
	{
		$$$TRACE("Successfully executed Query:"_tSQL)
		IF ($ISOBJECT(pRes)&&(pRes.RowCount>0)){
			$$$TRACE("Retrieve data from the Response, # of rows:" _ pRes.RowCount)
			set rowNum=pRes.Next(.sc)
			WHILE (rowNum > 0)
			{
				set dataRow = ##class(IHC.ITF.DStruc.Request.CORPPRV.MdmExtraFields).%New()
				set dataRow.PRVDRID = tPRVDR
				$$$TRACE("Error Status: "_sc)
				if ($$$ISERR(sc)){
					$$$TRACE("Error Reading result set")
					set tSC=$$$ERROR("Error Reading Result set")
				}else{
					$$$TRACE("rowNum "_rowNum _ ", " _ pRes.Get("FCILITY_ID") _ ", " _pRes.Get("PRMRY_FLG"))
					if ( pRes.Get("FCILITY_ID") '= "999")
					{
						set dataRow.CADVFAFCILITYID = pRes.Get("FCILITY_ID")
					}				
					if (pRes.Get("PRMRY_FLG") '= "999")
					{
					    set dataRow.CADVFAPRMRYFLG = pRes.Get("PRMRY_FLG")
					}
					if (pRes.Get("PRVDR_ID") '= "999")
					{
					    set dataRow.CADVFAPRVDRID = pRes.Get("PRVDR_ID")
					}
					if (pRes.Get("FCILITY_NM") '= "999")
					{
					    set dataRow.FACIFCILITYNM = pRes.Get("FCILITY_NM")
					}
					if (pRes.Get("SPCLTY_ID") '= "999")
					{
					    set dataRow.CADVSPSPCLTYID = pRes.Get("SPCLTY_ID")
					}
					if (pRes.Get("SPCLTY_DSC") '= "999")
					{
					    set dataRow.CSPSPCLTYDSC = pRes.Get("SPCLTY_DSC")
					}

					if (pRes.Get("PRIMARY_FLG") '= "999")
					{
					    set dataRow.CADVSPPRIMARYFLG = pRes.Get("PRIMARY_FLG")
					}

					DO list.Insert(dataRow)
					$$$TRACE("entry # " _ pResponse.mdmList.Count() )
				}
				set rowNum=pRes.Next(.sc)

			}
			set pResponse.mdmList = list
			$$$TRACE("Return Status: "_sc _", rowNum: " _ pResponse.mdmList.Count())

		}

	}
	else
	{
		$$$TRACE("Failed to execute Query:"_tSQL)	
	}

	Quit tSC
